css:
body [data-bz-node="ft"]{background:#141414;padding:48px 0 0;color:#fff}
body [data-bz-node="ft"] .bz-block{padding:0}
body [data-bz-node="ft"] .bz-container{padding:0}
body [data-bz-node="ft"]>.bz-container{max-width:var(--container)}
body [data-bz-node="ft-row"]>.bz-col{grid-column:auto}
body [data-bz-node="ft-row"]{display:grid;grid-template-columns:371fr 285fr 286fr 246fr;gap:0;padding-bottom:40px;align-items:start}
body [data-bz-node="ft-logo"]{margin-bottom:14px}
body [data-bz-node="ft-logo"] img{height:30px;width:auto}
body [data-bz-node="ft-address"] p{font:400 12.5px/22.5px var(--font-body);color:rgba(255,255,255,.88);margin:0}
body [data-bz-node="ft-address"] a{color:inherit}
body [data-bz-node="ft-address"] p:last-child{margin-top:4px;font-weight:500;color:#fff}
body [data-bz-node="ft-social"]{display:block;margin-top:17px}
body [data-bz-node="ft-social-col"]{display:flex;gap:18px}
body [data-bz-node="ft-social-col"] .bz-block{width:24px}
body [data-bz-node="ft-social-col"] img,body [data-bz-node="ft-social-col"] a{width:24px;height:24px;display:block}
body [data-bz-node="ft-social-col"] .bz-block:hover{opacity:.7}
body [data-bz-node="ft-row"] h3{font:700 11px/1 var(--font-heading);letter-spacing:.22em;text-transform:uppercase;color:#fff;margin:7px 0 18px}
body [data-bz-node="ft-row"] .bz-nav{flex-direction:column;align-items:flex-start;gap:0}
body [data-bz-node="ft-row"] .bz-navitem>a{padding:0;display:block;font:400 12.5px/32px var(--font-body);color:rgba(255,255,255,.9)}
body [data-bz-node="ft-row"] .bz-navitem>a:hover{color:var(--accent)}
body [data-bz-node="ft-bottom"]{display:flex;justify-content:space-between;align-items:center;gap:24px;border-top:1px solid #353535;padding:15px 0 20px;min-height:55px;box-sizing:border-box}
body [data-bz-node="ft-copy"] p{font:400 11px/1.4 var(--font-body);color:rgba(255,255,255,.7);margin:0}
body [data-bz-node="ft-built"]{display:flex;align-items:center;gap:8px;flex:0 0 auto}
body [data-bz-node="ft-built"]>.bz-block{width:auto}
body [data-bz-node="ft-built"] p{font:400 11px/1 var(--font-body);color:rgba(255,255,255,.7);margin:0}
body [data-bz-node="ft-built-logo"] img{width:52px;height:auto}
@media (max-width:1100px){
  body [data-bz-node="ft"]{padding:48px 24px 0}
  body [data-bz-node="ft-row"]{grid-template-columns:1fr 1fr;gap:36px 24px}
  body [data-bz-node="ft-row"]>[data-bz-node="ft-brand"]{grid-column:1/-1}
}
@media (max-width:640px){
  body [data-bz-node="ft"]{padding:40px 20px 0}
  body [data-bz-node="ft-row"]{grid-template-columns:1fr 1fr;gap:32px 16px}
  body [data-bz-node="ft-logo"] img{height:26px}
  body [data-bz-node="ft-bottom"]{flex-direction:column;align-items:flex-start;gap:12px}
}
